from ..recipe import Artifact, BuildStep, Recipe, Source


_PREPARE = r"""python - <<'PY'
from pathlib import Path
import os
import re
import shutil
import subprocess
assert subprocess.check_output(['go', 'version'], text=True).split()[2] == 'go1.20.14'
out = Path('corpus-analysis')
shutil.rmtree(out, ignore_errors=True)
entries = [p for p in Path('.').iterdir() if p.name not in ['.git', out.name]]
out.mkdir()
for p in entries:
    target = out / p.name
    if p.is_dir():
        shutil.copytree(p, target, copy_function=os.link, symlinks=True)
    else:
        os.link(p, target)
changed = []
for i, p in enumerate(sorted((out / 'implant/sliver').rglob('*.go'))):
    if p.name.endswith('_test.go'):
        continue
    old = p.read_text()
    new = re.sub(r'^func init\s*\(\s*\)', 'func corpusDisabledInit'+str(i)+'()', old, flags=re.M)
    if p == out / 'implant/sliver/sliver.go':
        assert new.count('import "C"') == 1
        assert new.count('func main() {') == 1
        new = new.replace('import "C"', '').replace('func main() {', 'func corpusOriginalMain() {')
        if '{goos}' != 'windows':
            assert new.count('"golang.org/x/sys/windows/svc"') == 1
            new = new.replace('"golang.org/x/sys/windows/svc"', '')
            new = new.replace('type sliverService struct{}', '')
            start = new.index('func (serv *sliverService) Execute(')
            brace = new.index('{', start)
            depth = 1
            end = brace + 1
            while depth:
                depth += (new[end] == '{') - (new[end] == '}')
                end += 1
            new = new[:start] + new[end:]
            assert new.count('svc.Run("", &sliverService{})') == 1
            new = new.replace('svc.Run("", &sliverService{})', '')
            # Select only the two existing OS branches, without rendering
            # any operator configuration, certificate, key or endpoint.
        lines = []
        depth = selected = 0
        windows = '{goos}' == 'windows'
        keep = False
        for line in new.splitlines(keepends=True):
            match = re.search(r'\{\{\s*(.*?)\s*\}\}', line) if line.lstrip().startswith('//') else None
            directive = match.group(1).strip() if match else ''
            if not depth:
                if directive == 'if eq .Config.GOOS "windows"':
                    depth, keep = 1, windows
                    selected += 1
                    continue
                lines.append(line)
                continue
            if directive.startswith(('if ', 'range ', 'with ')):
                depth += 1
            elif directive == 'end':
                depth -= 1
                if not depth:
                    continue
            elif directive == 'else' and depth == 1:
                keep = not windows
                continue
            if keep:
                lines.append(line)
        assert depth == 0 and selected == 2
        new = ''.join(lines)
    if new != old:
        # Replace the inode so hard-linked upstream files stay unchanged.
        temp = p.with_suffix('.corpus-tmp')
        temp.write_text(new)
        temp.replace(p)
        changed.append(str(p.relative_to(out)))
(out / 'implant/sliver/corpus_main.go').write_text(
    'package main\nimport "fmt"\nfunc main() { fmt.Printf("%p", corpusOriginalMain) }\n')
assert '{{.Config.ECCPrivateKey}}' in (out / 'implant/sliver/cryptography/implant.go').read_text()
print('Analysis-only changed files:', changed, flush=True)
PY"""


RECIPES = {
    'Sliver_1.5.42_go120_analysis': Recipe(
        family='Sliver', version='1.5.42-go1.20.14-analysis',
        upstream='https://github.com/BishopFox/sliver', license='GPL-3.0',
        source=Source(git_url='https://github.com/BishopFox/sliver.git',
                      git_ref='85b0e870d05ec47184958dbcb871ddee2eb9e3df'),
        build=[BuildStep(_PREPARE), BuildStep(
            'go build -mod=vendor -trimpath '
            '-gcflags=github.com/bishopfox/sliver/...=-l '
            '-o reference-sliver ./implant/sliver', cwd='corpus-analysis',
            env={'GOOS': '{goos}', 'GOARCH': '{goarch}', 'CGO_ENABLED': '0'})],
        artifacts=[Artifact(path='corpus-analysis/reference-sliver',
                            component='implant-analysis')],
        toolchains=['linux_x86', 'linux_x64', 'mingw_x86', 'mingw_x64'],
        requires=['go', 'python'], glue_filter='go',
        build_flags='Go 1.20.14; CGO_ENABLED=0; -mod=vendor -trimpath '
                    '-gcflags=github.com/bishopfox/sliver/...=-l; '
                    'inert address-only main; disabled first-party init; '
                    'cgo entry import omitted; target-OS dispatch branches '
                    'selected; Linux service adapter omitted',
        notes='Pinned v1.5.42 source and its source-controlled vendor tree. '
              'Go 1.20.14 satisfies the vendored gVisor version constraint. '
              'Only a hard-linked analysis copy is adapted, with atomic '
              'replacement preserving upstream files: omit the cgo entry '
              'import, rename original main and first-party initializers, '
              'and add an address-only main that calls no implant function. '
              'The target OS selects its two existing dispatch branches; '
              'Linux omits the Windows service adapter. All configuration, '
              'endpoint, certificate and key templates remain unexpanded. '
              'No operator profile, template generator, server or compiled '
              'program is run. This is a non-operational reference image. '
              'Vendored dependency functions remain and are reported '
              'separately from first-party namespace counts. Startup wrappers '
              'differ from upstream release builds. Platform ids describe '
              'target containers; Go 1.20.14 is the actual compiler.'),
}
